const $=s=>document.querySelector(s),clone=o=>JSON.parse(JSON.stringify(o));
const specs={diagonal:{W:[[1,1],[-1,-1],[1,0],[0,1]],b:[0,0,0,0],v:[6,-6,0,0],bias:0,description:'Class 1 when x + y is positive. Two ReLU units reconstruct a signed diagonal.',target:(x,y)=>x+y>0},band:{W:[[1,0],[-1,0],[0,1],[0,-1]],b:[0,0,0,0],v:[-8,-8,0,0],bias:3.2,description:'Class 1 inside the central strip: |x| < 0.4. Two units measure distance from the center.',target:(x,y)=>Math.abs(x)<.4},xor:{W:[[1,1],[-1,-1],[1,-1],[-1,1]],b:[0,0,0,0],v:[-6,-6,6,6],bias:0,description:'Class 1 when x and y have opposite signs. Four units compare diagonal distances.',target:(x,y)=>x*y<0}};
let key='diagonal',net,base,layer='output';const sigmoid=z=>1/(1+Math.exp(-z));
function predict(x,y,n=net){return sigmoid(n.W.reduce((s,w,i)=>s+n.v[i]*Math.max(0,w[0]*x+w[1]*y+n.b[i]),n.bias))}
function flat(n){return [...n.W.flat(),...n.b,...n.v,n.bias]}
function start(){const s=specs[key];net={W:clone(s.W),b:[...s.b],v:[...s.v],bias:s.bias};net.v[0]*=-1;base=clone(net);$('#description').textContent=s.description;$('#status').textContent='● Baseline loaded';sliders();render()}
function sliders(){const rows=layer==='output'?[...net.v.map((v,i)=>({name:`v[${i}]`,v,set:x=>net.v[i]=x})),{name:'bias',v:net.bias,set:x=>net.bias=x}]:[...net.W.flatMap((w,i)=>w.map((v,j)=>({name:`W[${i},${j}]`,v,set:x=>net.W[i][j]=x}))),...net.b.map((v,i)=>({name:`b[${i}]`,v,set:x=>net.b[i]=x}))];$('#sliders').replaceChildren();rows.forEach((r,i)=>{const div=document.createElement('div');div.className='slider-row';const label=document.createElement('label');label.htmlFor='weight'+i;label.textContent=r.name;const input=document.createElement('input');Object.assign(input,{type:'range',min:Math.min(-12,Math.floor(r.v)),max:Math.max(12,Math.ceil(r.v)),step:.1,value:r.v,id:'weight'+i});const out=document.createElement('output');out.textContent=r.v.toFixed(1);input.oninput=()=>{r.set(+input.value);out.textContent=(+input.value).toFixed(1);$('#status').textContent='● Custom weights · live';render()};div.append(label,input,out);$('#sliders').append(div)})}
const canvas=$('#plot'),ctx=canvas.getContext('2d');
function render(){const w=canvas.width,h=canvas.height,im=ctx.createImageData(w,h);for(let j=0;j<h;j++)for(let i=0;i<w;i++){const p=predict(i/(w-1)*2-1,1-j/(h-1)*2),k=(j*w+i)*4;const a=[100,83,153],b=[175,205,118];for(let c=0;c<3;c++)im.data[k+c]=a[c]*(1-p)+b[c]*p;im.data[k+3]=255}ctx.putImageData(im,0,0);ctx.strokeStyle='#e2e9d922';ctx.lineWidth=1;for(let i=1;i<8;i++){ctx.beginPath();ctx.moveTo(w*i/8,0);ctx.lineTo(w*i/8,h);ctx.stroke();ctx.beginPath();ctx.moveTo(0,h*i/8);ctx.lineTo(w,h*i/8);ctx.stroke()}ctx.setLineDash([3,5]);ctx.strokeStyle='#edf4dc88';ctx.beginPath();ctx.moveTo(w/2,0);ctx.lineTo(w/2,h);ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();ctx.setLineDash([]);ctx.font='9px monospace';ctx.fillStyle='#f0f3e5aa';ctx.fillText('−1',8,h-9);ctx.fillText('+1',w-23,h-9);ctx.fillText('+1',8,15);
let correct=0;for(let y=0;y<41;y++)for(let x=0;x<41;x++){const a=(x-20)/20,b=(y-20)/20;if((predict(a,b)>.5)===specs[key].target(a,b))correct++}const pct=correct/1681*100;$('#accuracy').textContent=pct.toFixed(1)+'%';$('#bar').style.width=pct+'%';const f=flat(base),count=flat(net).filter((v,i)=>Math.abs(v-f[i])>1e-7).length;$('#changed').innerHTML=count+' <em>/ 17</em>'}
$('#preset').onchange=e=>{key=e.target.value;start()};$('#reset').onclick=start;$('#fix').onclick=()=>{const s=specs[key];net={W:clone(s.W),b:[...s.b],v:[...s.v],bias:s.bias};sliders();render();$('#status').textContent='● Crafted weights applied'};document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{layer=b.dataset.layer;document.querySelectorAll('[data-layer]').forEach(t=>t.classList.toggle('selected',t===b));sliders()});
canvas.onpointermove=e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*2-1,y=1-(e.clientY-r.top)/r.height*2;$('#probe').textContent=`(${x.toFixed(2)}, ${y.toFixed(2)}) → ${predict(x,y).toFixed(3)}`};canvas.onpointerleave=()=>$('#probe').textContent='Hover to inspect →';$('#export').onclick=()=>{const data={format:'weightspace-lab-v1',pattern:key,architecture:[2,4,1],activations:['relu','sigmoid'],weights:net};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`weightspace-${key}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};start();
